   357|function resolveSendBranch(
   358|  deliveryBranch: DeliveryBranchStatus['branch'],
   359|  runtimeSource: RuntimeDebugSnapshot['source'],
   360|  httpStatus: string,
   361|): SendBranchProofRow {
   362|  if (deliveryBranch === 'not_observed') {
   363|    return { branch: null, label: 'pending', context: 'no send observed' };
   364|  }
   365|
   366|  const statusFragment = httpStatus !== 'pending' && httpStatus !== 'none' ? ` · ${httpStatus}` : '';
   367|
   368|  if (deliveryBranch === 'remote_db_insert') {
   369|    if (runtimeSource === 'remote_api' || runtimeSource === 'local_app_brain') {
   370|      return { branch: 'primary_realtime', label: 'primary_realtime', context: `assistant db insert${statusFragment}` };
   371|    }
   372|    if (runtimeSource === 'provider_fallback') {
   373|      return { branch: 'alternate_shared', label: 'alternate_shared', context: `gateway db insert${statusFragment}` };
   374|    }
   375|    return { branch: 'primary_realtime', label: 'primary_realtime', context: `db insert · source ${runtimeSource}${statusFragment}` };
   376|  }
   377|
   378|  if (deliveryBranch === 'local_fallback') {
   379|    return { branch: 'snapshot_fallback', label: 'snapshot_fallback', context: `local fallback path${statusFragment}` };
   380|  }
   381|
   382|  if (deliveryBranch === 'auth_session_failure') {
