   562|
   563|async function fetchOwnerAIProxyStatus(audit: IVXOwnerAIConfigAudit): Promise<AIProxyStatusSnapshot> {
   564|  const url = buildOwnerAIProxyStatusUrl(audit);
   565|  if (!url) {
   566|    return {
   567|      ...createInitialAIProxyStatus(),
   568|      status: 'error',
   569|      error: audit.configurationError ?? 'Owner AI proxy status URL is not configured.',
   570|    };
   571|  }
   572|
   573|  const accessToken = await getIVXAccessToken();
   574|  if (!accessToken) {
   575|    return {
   576|      ...createInitialAIProxyStatus(),
   577|      status: 'blocked',
   578|      observedAt: new Date().toISOString(),
   579|      url,
   580|      error: 'Owner session token is not hydrated yet.',
   581|    };
   582|  }
   583|
   584|  const controller = new AbortController();
   585|  const timer = setTimeout(() => {
   586|    controller.abort();
   587|  }, AI_FAST_PROXY_TIMEOUT_MS);
   588|
   589|  try {
   590|    const response = await fetch(url, {
   591|      method: 'GET',
   592|      headers: {
   593|        Accept: 'application/json',
   594|        Authorization: `Bearer ${accessToken}`,
   595|      },
   596|      signal: controller.signal,
   597|    });
   598|    const payload = await response.json().catch(() => null) as Record<string, unknown> | null;
   599|    const runtime = isRecord(payload?.runtime) ? payload.runtime : {};
   600|    const runtimeConfigured = runtime.configured === true;
   601|    const deploymentMarker = typeof payload?.deploymentMarker === 'string' ? payload.deploymentMarker : null;
   602|    const model = typeof runtime.model === 'string' ? runtime.model : null;
   603|    const gateway = typeof runtime.gateway === 'string' ? runtime.gateway : null;
   604|    const error = typeof payload?.error === 'string' ? payload.error : typeof payload?.detail === 'string' ? payload.detail : null;
   605|
   606|    if (!response.ok) {
   607|      return {
   608|        status: response.status === 401 || response.status === 403 ? 'blocked' : 'error',
   609|        observedAt: new Date().toISOString(),
   610|        url,
   611|        model,
   612|        gateway,
   613|        configured: false,
   614|        deploymentMarker,
   615|        error: error ?? `Proxy status returned HTTP ${response.status}.`,
   616|      };
   617|    }
   618|
   619|    return {
   620|      status: runtimeConfigured ? 'connected' : 'error',
   621|      observedAt: new Date().toISOString(),
   622|      url,
   623|      model,
   624|      gateway,
   625|      configured: runtimeConfigured,
   626|      deploymentMarker,
   627|      error: runtimeConfigured ? null : 'Proxy route is live, but AI gateway configuration is not ready.',
   628|    };
   629|  } catch (error) {
   630|    return {
   631|      ...createInitialAIProxyStatus(),
   632|      status: 'error',
   633|      observedAt: new Date().toISOString(),
   634|      url,
   635|      error: error instanceof Error ? error.message : 'Unable to reach Owner AI proxy status.',
   636|    };
   637|  } finally {
   638|    clearTimeout(timer);
   639|  }
   640|}
