   730|function parseOwnerCommand(text: string): OwnerCommandResult | null {
   731|  const trimmed = safeTrim(text);
   732|  if (!trimmed.startsWith(OWNER_COMMAND_PREFIX)) return null;
   733|  const parts = trimmed.slice(OWNER_COMMAND_PREFIX.length).split(/\s+/);
   734|  const command = (parts[0] ?? '').toLowerCase();
   735|  const args = parts.slice(1).join(' ');
   736|  if (!command) return null;
   737|  const handler = OWNER_COMMANDS[command];
   738|  if (!handler) return { command, args, response: `Unknown command: /${command}. Type /help for available commands.` };
   739|  console.log('[IVXOwnerChatRoute] Owner command detected:', command, 'args:', args);
   740|  return { command, args, response: handler.handler(args) };
